"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["69834"],{55876(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>c,frontMatter:()=>r,contentTitle:()=>h,toc:()=>l,assets:()=>o});var i=JSON.parse('{"id":"others/yinfujing","title":"","description":"Written by Xu Dachun of Wujiang","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/others/yinfujing.md","sourceDirName":"others","slug":"/others/yinfujing","permalink":"/en/others/yinfujing","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"yinfujing","title":"","hide_table_of_contents":true,"sidebar_label":"Commentary on the Yinfu Jing (by Xu Dachun)"},"sidebar":"othersSidebar","next":{"title":"Heart Sutra (Mah\u0101praj\xf1\u0101p\u0101ramit\u0101 H\u1E5Bdaya)","permalink":"/en/others/heartsutra"}}'),s=t(74848),a=t(28453);let r={id:"yinfujing",title:"",hide_table_of_contents:!0,sidebar_label:"Commentary on the Yinfu Jing (by Xu Dachun)"},h="Commentary on the Yin Fu Jing (Scripture of the Hidden Talisman)",o={},l=[{value:"Upper Chapter",id:"upper-chapter",level:2},{value:"Middle Chapter",id:"middle-chapter",level:2},{value:"Lower Chapter",id:"lower-chapter",level:2},{value:"Upper Chapter",id:"upper-chapter-1",level:2},{value:"Middle Chapter",id:"middle-chapter-1",level:2},{value:"Lower Chapter",id:"lower-chapter-1",level:2}];function d(e){let n={blockquote:"blockquote",em:"em",h1:"h1",h2:"h2",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"commentary-on-the-yin-fu-jing-scripture-of-the-hidden-talisman",children:"Commentary on the Yin Fu Jing (Scripture of the Hidden Talisman)"})}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:"Written by Xu Dachun of Wujiang"}),"\n"]}),"\n",(0,s.jsx)(n.h1,{id:"original-text",children:"Original Text"}),"\n",(0,s.jsx)(n.h2,{id:"upper-chapter",children:"Upper Chapter"}),"\n",(0,s.jsx)(n.p,{children:"Observe the Dao of Heaven, grasp the workings of Heaven \u2014 that is all. Heaven has five thieves; he who perceives them prospers. The five thieves reside in the mind; their application extends through Heaven. The universe is in one's hands; all transformations are born from one's body. Heaven's nature is man; man's mind is the trigger. Establish the Dao of Heaven to settle the affairs of man. When Heaven unleashes the killing impulse, stars shift and constellations change; when Earth unleashes the killing impulse, dragons and serpents rise from land; when Man unleashes the killing impulse, Heaven and Earth are overturned. When Heaven and Man strike together, the foundation of ten thousand transformations is fixed. Natures are clever or clumsy, and can be concealed. The evils of the nine orifices lie in three essentials, which can bring motion or stillness. Fire born in wood \u2014 when calamity erupts, it must consume; treachery born in a state \u2014 when the time comes, it must collapse. He who knows this and cultivates accordingly is called a sage."}),"\n",(0,s.jsx)(n.h2,{id:"middle-chapter",children:"Middle Chapter"}),"\n",(0,s.jsx)(n.p,{children:"Heaven gives life and Heaven kills \u2014 this is the principle of the Dao. Heaven and Earth are the thieves of the myriad things; the myriad things are the thieves of man; man is the thief of the myriad things. When the three thievings are appropriate, the Three Powers are at peace. Therefore it is said: eat in accordance with the seasons, and the hundred joints are well-ordered; act in accordance with the trigger, and the ten thousand transformations are at peace. Men know what makes their spirit spirited, but do not know what makes their spirit so. The sun and moon have their numbers; the greater and lesser have their fixed measures. From these, the sage's merits are born; from these, divine illumination emerges. The trigger of thieving \u2014 none under Heaven can see it, none can know it. When the noble person obtains it, they fortify their person; when the petty person obtains it, they treat life lightly."}),"\n",(0,s.jsx)(n.h2,{id:"lower-chapter",children:"Lower Chapter"}),"\n",(0,s.jsx)(n.p,{children:"The blind are good at hearing; the deaf are good at seeing. Cut off the one source of profit, and it equals tenfold the use of a teacher; reflect thrice day and night, and it equals ten-thousand-fold the use of a teacher. The mind is born from things and dies by things; the trigger lies in the eyes. Heaven's absence of grace gives birth to great grace. Before thunderclap and fierce wind, nothing fails to stir. The height of joy overflows one's nature; the height of stillness sharpens it. Heaven's supreme partiality \u2014 in its use, supreme impartiality. The mastery of living things lies in qi. What lives is the root of death; what dies is the root of life. Grace is born from harm; harm is born from grace. The fool takes Heaven and Earth's patterns as saintly; I take the patterns of timely things as wise. People deem the fool's reckoning as saintly; I deem not-foolish reckoning as saintly. People expect sainthood through the extraordinary; I expect sainthood through the ordinary. Therefore it is said: sinking in water, entering fire \u2014 one brings about one's own destruction. The way of Nature is stillness; therefore Heaven, Earth, and the myriad things come into being. The way of Heaven and Earth is gradual; therefore yin and yang prevail. Yin and yang press upon each other, and transformation follows in accord. Therefore the sage knows the way of Nature cannot be violated, and thus governs accordingly. The way of utmost stillness \u2014 even the pitch-pipes and calendar cannot match it. Yet there exists a marvelous instrument from which the ten thousand images are born: the Eight Trigrams and the Sexagenary Cycle \u2014 divine triggers, ghostly concealment. The art by which yin and yang overcome each other is made luminously clear and manifest in images."}),"\n",(0,s.jsx)(n.h1,{id:"original-preface-to-the-yin-fu-jing",children:"Original Preface to the Yin Fu Jing"}),"\n",(0,s.jsxs)(n.p,{children:["The Yin Fu Jing is a book that elucidates the ",(0,s.jsx)(n.em,{children:"Yi Jing"}),' (Book of Changes). Its final chapter speaks of "marvelous instruments," referring to the Eight Trigrams and the Sexagenary Cycle. The book\'s secrets lie entirely within these two systems; all the preceding and following discussions serve to explicate them. The ',(0,s.jsx)(n.em,{children:"Yi Jing"})," as a book, though expounded by four sages, still has secrets of application not fully addressed. The ",(0,s.jsx)(n.em,{children:"Yin Fu Jing"}),' identifies and names them: "the five thieves," "the killing impulse," "the three essentials," "the three thievings," "the trigger lies in the eyes," "the mastery of living things lies in qi." He who truly understands these several principles can truly hold the universe in his hands, generate all transformations from his body, and execute the workings of Heaven. These are secrets of Heaven and Earth that sages would not lightly speak of, yet the ',(0,s.jsx)(n.em,{children:"Yin Fu Jing"})," reveals them. However, the ",(0,s.jsx)(n.em,{children:"Yi Jing"})," as a book is vast and all-encompassing; what each person sees in it is complete according to their vision. As it is said, the benevolent see it and call it benevolence; the wise see it and call it wisdom. The author of the ",(0,s.jsx)(n.em,{children:"Yin Fu Jing"})," saw the ",(0,s.jsx)(n.em,{children:"Yi Jing"})," in this particular way, though the totality of the ",(0,s.jsx)(n.em,{children:"Yi Jing"})," is not necessarily confined to this. What the ",(0,s.jsx)(n.em,{children:"Yin Fu Jing"})," sees of the ",(0,s.jsx)(n.em,{children:"Yi Jing"})," constitutes the ",(0,s.jsx)(n.em,{children:"Yin Fu Jing"}),"'s own ",(0,s.jsx)(n.em,{children:"Yi Jing"}),", nothing more. Yet to benefit from the ",(0,s.jsx)(n.em,{children:"Yin Fu Jing"}),"'s perspective requires a good reader of the ",(0,s.jsx)(n.em,{children:"Yin Fu Jing"}),". A poor reader would think the entirety of the ",(0,s.jsx)(n.em,{children:"Yi Jing"}),"'s way resides in the ",(0,s.jsx)(n.em,{children:"Yin Fu Jing"}),", and then further misinterpret the ",(0,s.jsx)(n.em,{children:"Yin Fu Jing"})," itself, seeing it as a book of strange and perilous stratagems \u2014 thereby losing the Dao of the ",(0,s.jsx)(n.em,{children:"Yi Jing"}),'. Hence the middle chapter\'s warning: "When the noble person obtains it, they fortify their person; when the petty person obtains it, they treat life lightly." This is precisely a caution against poor readers of the ',(0,s.jsx)(n.em,{children:"Yin Fu Jing"}),". If, then, the reader can avoid viewing it as a strange and perilous book and instead see it as a work that illuminates the principles of the ",(0,s.jsx)(n.em,{children:"Yi Jing"}),", penetrating its subtleties while extending its meaning to exhaust the full principle of the ",(0,s.jsx)(n.em,{children:"Yi Jing"})," \u2014 then the ",(0,s.jsx)(n.em,{children:"Yin Fu Jing"})," is understood, and the Dao of the ",(0,s.jsx)(n.em,{children:"Yi Jing"})," is likewise understood. Hence I say the ",(0,s.jsx)(n.em,{children:"Yin Fu Jing"})," is a book that elucidates the ",(0,s.jsx)(n.em,{children:"Yi Jing"}),". As for the book's origins, some attribute it to the Yellow Emperor, some to the Warring States period, some consider it a forgery by Li Quan of the Tang dynasty \u2014 none can be determined with certainty. Its depth and profundity could only have been composed by one who had attained the essence of the Yellow Emperor and Laozi traditions. Following its intent, one may apply it to nourishing life, governing the state, and employing military strategy \u2014 nothing is beyond its scope. To insist on attributing it to any particular author is mere speculation!"]}),"\n",(0,s.jsx)("div",{style:{textAlign:"right"},children:(0,s.jsxs)(n.p,{children:["In the twenty-fifth year of Qianlong's reign,",(0,s.jsx)("br",{}),"\nIn the last decade of the second month, at Huixi,",(0,s.jsx)("br",{}),"\nPreface by Xu Dachun"]})}),"\n",(0,s.jsx)(n.h1,{id:"commentary",children:"Commentary"}),"\n",(0,s.jsx)(n.h2,{id:"upper-chapter-1",children:"Upper Chapter"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Observe the Dao of Heaven"})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'The Dao of Heaven is what Heaven governs \u2014 that which stands prior to form and vital energy. To "observe" is to investigate and scrutinize with precision; thus the substance of Heaven may be illuminated.'}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Grasp the workings of Heaven"})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'The "workings" of Heaven are the turning of Heaven\'s Dao \u2014 that which stirs and moves all things. To "grasp" is to hold and control, extending or retracting at will; thus the function of Heaven may be held in one\'s hand.'}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"That is all."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"The vastness of the universe is all encompassed by Heaven. With Heaven's substance and function in my possession, what further matter exists beyond Heaven?"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Heaven has five thieves; he who perceives them prospers."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'The five thieves are the Five Phases (wuxing). Although the Five Phases cycle through mutual generation, they must also mutually conquer and steal from one another, causing all things to be destroyed before being reborn. Their function lies not in generating but in conquering \u2014 hence they are called "thieves." If I can perceive this principle with clarity, my accomplishments will surely flourish.'}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The five thieves reside in the mind; their application extends through Heaven."})}),"\n"]}),"\n",(0,s.jsxs)(n.p,{children:['"In the mind" means to know them clearly and store them securely, making them one with the mind. "Application" refers to what the ',(0,s.jsx)(n.em,{children:"Yi Jing"}),' calls "the method of pruning and assisting" \u2014 all affairs under Heaven are done by Heaven, hence it says not "under Heaven" but simply "Heaven."']}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The universe is in one's hands; all transformations are born from one's body."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'"Universe" encompasses past and present; "in one\'s hands" means I grasp and manipulate it. "Ten thousand transformations" spans all beings and things; "born from one\'s body" means I nurture and cultivate them.'}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Heaven's nature is man."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Man is born of Heaven. Heaven's nature is invisible; it generates man, and the nature is thereby present in man. Hence human nature is the visible expression of Heavenly nature."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Man's mind is the trigger."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'Man has a mind. When the mind is unmoved, nothing is visible. But with the slightest stimulus, the mind reveals its edge \u2014 this is the "trigger." Once the mind has acted, interests, desires, and cravings may disrupt it, and the original mind may change. Only the very first impulse of thought is the most genuine.'}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Establish the Dao of Heaven to settle the affairs of man."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Man and Heaven are both born of the same vital energy and are fundamentally not two separate bodies. One must penetrate the Dao of Heaven and hold it without loss \u2014 this is what completes man's being as man, establishing firm and unshakeable ground."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"When Heaven unleashes the killing impulse, stars shift and constellations change."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"The trigger is not only in man \u2014 Heaven and Earth also possess it. Within the trigger there is also a killing impulse. When Heaven's killing impulse is activated, even fixed stars and constellations are thrown into disorder, leaving their established positions and reversing their normal courses."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"When Earth unleashes the killing impulse, dragons and serpents rise from land."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"When Earth's killing impulse is activated, dragons and serpents lying dormant will rise, shed their skins, and refuse to remain in their dens."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"When Man unleashes the killing impulse, Heaven and Earth are overturned."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"When Man's killing impulse is activated, desiring to achieve great deeds, one must turn Heaven and Earth upside down, shaking the cosmos."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"When Heaven and Man strike together, the foundation of ten thousand transformations is fixed."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"When Heaven and Man each act separately without resonance, circumstances are uneven \u2014 sometimes erupting and then subsiding, sometimes subsiding and then erupting again, in endless chaos. But when Heaven and Man strike simultaneously, extreme action gives way to the desire for stillness, extreme chaos to the desire for order. All things and affairs return to their beginning, and the foundation is thereby established."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Natures are clever or clumsy, and can be concealed."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Every person's nature has its own particular strengths \u2014 some in cleverness, some in simplicity \u2014 and even a sage cannot make them uniform. One should skillfully use one's nature: whether clever or simple, conceal it without display, so others cannot probe it. Then one's stratagems run deep, and one can exclusively exploit one's strengths."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The evils of the nine orifices lie in three essentials."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"The eyes, ears, mouth, nose, and two lower orifices are the nine apertures. The most important among them are the eyes and ears, which can see and hear, and the mouth, which can discuss and discourse \u2014 these are where spirit and intelligence reside. The rest are merely passages for blood, flesh, form, and vital energy."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Which can bring motion or stillness."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"These three, when active, extend vital intelligence in all directions; when still, they store spirit and essence within. Whether to act or to be still \u2014 one can be master of it."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Fire born in wood \u2014 when calamity erupts, it must consume; treachery born in a state \u2014 when the time comes, it must collapse."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Fire is inherent in wood; when it has not yet ignited, fire is invisible. But when the wood's moisture is depleted and fire's nature is unchecked, calamity erupts and the wood burns. Treachery is inherent in a state; when it has not yet surfaced, treachery is unknowable. But when the state's fortune wanes and plotters gain their moment, the time has come and the state collapses."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"He who knows this and cultivates accordingly is called a sage."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"If one can discern the inevitability of these principles, detect the trigger before it moves, prevent it through wisdom, and control it through method \u2014 so that ruin is averted \u2014 this is truly establishing the Dao of Heaven to settle the affairs of man. Only a sage can do this."}),"\n",(0,s.jsx)(n.h2,{id:"middle-chapter-1",children:"Middle Chapter"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Heaven gives life and Heaven kills \u2014 this is the principle of the Dao."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'All things are born of Heaven, hence "Heaven gives life." But there is also "Heaven kills." To give life and to kill \u2014 this constitutes the Dao. That life necessarily entails killing, and killing necessarily brings rebirth \u2014 this is the natural course of things, the very meaning of "principle."'}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Heaven and Earth are the thieves of the myriad things."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'What can take from and harm is called a "thief." Heaven and Earth generate the myriad things, then swiftly kill them \u2014 are they not the thieves of the myriad things?'}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The myriad things are the thieves of man."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Among the myriad things, there is a distinction between man and thing. Man cannot live without the myriad things for food, tools, and sustenance. Yet through them, man's desires grow, and he drowns and perishes \u2014 are the myriad things not man's thief?"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Man is the thief of the myriad things."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Without man, the myriad things cannot fulfill their propagation and flourishing. Yet in providing for man's use, they cannot avoid being felled and harmed \u2014 is man not the thief of the myriad things?"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"When the three thievings are appropriate, the Three Powers are at peace."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'When the thieving among the three is neither excessive, premature, perverse, nor erroneous \u2014 each finding its proper measure \u2014 then within mutual conquest lies the principle of mutual generation. Cycling endlessly, each rests in its place without discord. This is what is meant by "Heaven and Earth are in their positions, and the myriad things are nourished."'}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Therefore it is said: eat in accordance with the seasons, and the hundred joints are well-ordered; act in accordance with the trigger, and the ten thousand transformations are at peace."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'These two sentences are ancient sayings, cited to illustrate the above meaning. If one eats in accordance with the proper season, one\'s spirit is harmonious and the hundred joints are at ease. If one acts in accordance with the proper trigger, all affairs proceed in order and the myriad things are at peace. This is what "the Three Powers are at peace" means.'}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Men know what makes their spirit spirited, but do not know what makes their spirit so."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"People see only the marvelous effects of one who embodies the Dao and consider them divine. They do not know the means by which this divinity is achieved. The art of supreme mystery lies entirely in understanding the principle of the three thievings \u2014 of life and death \u2014 and being able to arrange them appropriately. Hence there is nothing that cannot be at peace."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The sun and moon have their numbers; the greater and lesser have their fixed measures. From these, the sage's merits are born; from these, divine illumination emerges."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"The courses of sun and moon follow fixed numbers; hence the large and small months are determined without error, and the new and full moons can be calibrated. The sage extrapolates and measures these, observes the Dao and grasps the workings, acts never at odds with the seasons \u2014 thus accomplishment is easily established, and through further refinement and illumination, wisdom is all-encompassing."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The trigger of thieving \u2014 none under Heaven can see it, none can know it."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"The application of the three thievings always lies in the moment between incipient motion and stillness. Once the trigger has fired, it can no longer be controlled. But at that moment, with no outward sign yet visible \u2014 who can see it? Who can know it?"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"When the noble person obtains it, they fortify their person; when the petty person obtains it, they treat life lightly."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Though the trigger is not easily known, different people come to know it. If such a person is a noble one, they cultivate themselves, await their time, and act when the moment comes \u2014 this is the art of protecting oneself through wisdom. If such a person is a petty one, they presume upon their talent and act recklessly against the times \u2014 only bringing about their own destruction. Thus the noble person's attainment is true attainment; the petty person's attainment, though they think they have attained, runs directly counter to the Dao."}),"\n",(0,s.jsx)(n.h2,{id:"lower-chapter-1",children:"Lower Chapter"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The blind are good at hearing; the deaf are good at seeing."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"When one faculty is lost, another can surpass ordinary capacity."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Cut off the one source of profit, and it equals tenfold the use of a teacher; reflect thrice day and night, and it equals ten-thousand-fold the use of a teacher."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Cut off the one source of profit and desire \u2014 the mind concentrates on one point with increased clarity. The benefit surpasses ten times that of learning from a teacher, just as the blind person's spirit concentrates on hearing and the deaf person's on seeing. If one further reflects and reflects again, turning it over thrice through day and night without cease, then the benefit of such single-minded purity surpasses ten thousand times that of a teacher. This is what is meant by \"being one's own teacher.\""}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The mind is born from things and dies by things."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'If there were nothing in the world, man would have no occasion to use his mind. As Laozi said, "Not seeing desirable things keeps the mind undisturbed." Hence the mind must be born from things. Yet when desire runs wild, emotion overwhelms, affairs multiply, and spirit is exhausted, the mind also dies because of things.'}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The trigger lies in the eyes."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"The mind cannot directly contact things. It must see the form of things, and then the mind follows. Therefore, at the juncture where things and mind meet, the eyes are paramount."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Heaven's absence of grace gives birth to great grace. Before thunderclap and fierce wind, nothing fails to stir."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Heaven generates things, letting them grow and develop on their own, never intentionally bestowing grace. Yet all things bear Heaven overhead and look up to its virtue \u2014 is this not grace at its greatest? Even the sudden thunderclap and fierce gale \u2014 these are simply Heaven's yang energy bursting forth in vigorous agitation, not deliberately bestowing virtue upon things. Yet all things that encounter them are startled and stirred, and the vital impulse of growth and flourishing is thereby set into greater motion. Is not the greatest grace contained in what appears graceless?"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The height of joy overflows one's nature; the height of stillness sharpens it."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Each thing has its own nature. When a person reaches the height of joy, their nature is necessarily relaxed and expansive. When a person reaches the height of stillness, their nature is necessarily meticulous and austere. This is natural disposition \u2014 it cannot be forced."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Heaven's supreme partiality \u2014 in its use, supreme impartiality. The mastery of living things lies in qi."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Heaven treats the myriad things differently \u2014 nurturing some, toppling others, with infinite variety. This seems like partiality. In truth, the reasons for nurturing or toppling are self-incurred by the myriad things. Heaven merely returns to each according to its own. In essence, it is the height of impartiality. And its governing method is simply one qi \u2014 as in spring's birth, summer's growth, autumn's gathering, winter's storing \u2014 nothing beyond the turning of one qi. \"Qin\" (\u79BD) is interchangeable with \"qin\" (\u64D2, to grasp/master)."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"What lives is the root of death; what dies is the root of life."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'All things that live must die \u2014 hence life is the root of death. Where there is death, there must be life \u2014 hence death is the root of life. The first sentence refers to individual things; the second refers to all things collectively. For what lives cannot avoid death; what dies cannot be reborn. When we say "the root of life," we mean: this one dies, and another is born.'}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Grace is born from harm; harm is born from grace."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"In human relations, where there is grace there must be harm, where there is harm there must be grace. There has never been a case entirely of one or the other \u2014 it is the nature of things."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The fool takes Heaven and Earth's patterns as saintly; I take the patterns of timely things as wise."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"The fools of this world believe that to understand Heaven and Earth's patterns, one must be a sage. I say that Heaven and Earth's patterns are not directly graspable, but the timely manifestations of Heaven and Earth's workings are plainly visible. He who can discern these is a sage \u2014 and this sage is what we call a philosopher. The \"patterns of timely things\" refers to the meaning of \"Heaven's supreme partiality\" and what follows in the preceding text."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"People deem the fool's reckoning as saintly; I deem not-foolish reckoning as saintly. People expect sainthood through the extraordinary; I expect sainthood through the ordinary."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"The people of this world, each pursuing their own interests without established views, sometimes consider the sage naively rigid and somewhat foolish, sometimes consider the sage divinely transformative and somewhat extraordinary. I believe the sage truly perceives Heaven and Earth and nurtures all things \u2014 not merely not-foolish, but also not-extraordinary."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Therefore it is said: sinking in water, entering fire \u2014 one brings about one's own destruction."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"The sage is neither foolish nor extraordinary. Ordinary people are either one or the other. Relying on their own wits, pursuing profit and indulging desire, they think they have found the best method for survival, when in fact they have planted the seeds of their own destruction \u2014 like throwing themselves into water or fire. Their ruin is certain."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The way of Nature is stillness; therefore Heaven, Earth, and the myriad things come into being."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"The myriad things are born of Heaven and Earth, and Heaven and Earth are in turn born of the Dao. This Dao is the way of Nature. The substance of the Dao is unfathomably deep, utterly still and unmoving \u2014 the height of stillness and non-action. Precisely because of its utmost stillness, it encompasses everything. All that has form and vital energy emerges from it, filling the space between Heaven and Earth \u2014 all permeated by the Dao."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The way of Heaven and Earth is gradual; therefore yin and yang prevail."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"After Heaven and Earth are born, the Dao dwells within them. What operates within Heaven and Earth is simply the two principles of yin and yang. Between Heaven and Earth, these two principles can never remain in perfect balance for an entire year \u2014 they must alternately wax and wane for the year's work to be accomplished. And the manner of their waxing and waning is not abrupt \u2014 it must proceed from the subtle to the manifest, gradually accumulating to an extreme, then declining. As when one yang is born at the winter solstice and yang reaches its extreme by the fourth month; one yin is born at the summer solstice and yin reaches its extreme by the tenth month \u2014 this is precisely the meaning."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Yin and yang press upon each other, and transformation follows in accord."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'When yin reaches its extreme, yang is born; when yang reaches its extreme, yin is born \u2014 this is what is meant by "pressing upon each other." From this, the four seasons proceed and the myriad things come into being \u2014 this is what is meant by "transformation follows in accord."'}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Therefore the sage knows the way of Nature cannot be violated, and thus governs accordingly."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"All the above pertains to the way of Nature. The sage penetrates it through insight and spiritual communion, knowing that nothing under Heaven can escape its scope, and accordingly prunes and assists."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"The way of utmost stillness \u2014 even the pitch-pipes and calendar cannot match it."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"The way of Nature is stillness, hence it is also called the way of utmost stillness. Its substance is without form or image. Even the most refined and subtle methods, such as the pitch-pipe and calendar systems, still carry traces of instruments and numbers. They ultimately cannot match and merge with the Dao without gap."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Yet there exists a marvelous instrument from which the ten thousand images are born: the Eight Trigrams and the Sexagenary Cycle \u2014 divine triggers, ghostly concealment. The art by which yin and yang overcome each other is made luminously clear and manifest in images."})}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"The Dao cannot be matched. Yet the sage will not rest content without seeking to match the Dao. Therefore, he devises a marvelous instrument for matching the Dao. Its structure is exceedingly simple, yet the images of all things are born from it. What is this instrument? It is the Eight Trigrams and the Sexagenary Cycle. With the Eight Trigrams established, Heaven, Earth, and the Five Phases cannot stand outside them. With the Sexagenary Cycle fixed, the years, seasons, days, and months cannot deviate from them. Even changes as spiritually mysterious and unpredictably hidden as those of ghosts and spirits, as unfathomable as yin and yang \u2014 within the Eight Trigrams and Sexagenary Cycle, no principle is not encompassed, no number is not included. Their meaning is luminously clear, giving people images to follow. Thus what the pitch-pipes and calendar cannot match is now revealed in its every subtlety."})]})}function c(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,n,t){t.d(n,{R:()=>r,x:()=>h});var i=t(96540);let s={},a=i.createContext(s);function r(e){let n=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function h(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),i.createElement(a.Provider,{value:n},e.children)}}}]);